def transform_by_frequency(grid):
    """Map based on frequency: highest→9, next→8, etc."""
    # Count frequencies
    h, w = len(grid), len(grid[0])
    counts = {}
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1

    # Sort by count descending
    sorted_colors = sorted(counts.items(), key=lambda x: -x[1])

    # Map top N colors to 9, 8, 7, ...
    mapping = {color: idx+1 for idx, (color, _) in enumerate(sorted_colors)}

    # Actually, let's use 9 for most freq, 8 for second, etc. but need unique colors
    # Using reverse order from 9 down
    mapping = {sorted_colors[i][0]: 9 - i for i in range(len(sorted_colors))}

    return [[mapping[cell] for cell in row] for row in grid]

